<style>
:root{--night:#101f2a;--cream:#fff0cd;--orange:#ff9c46;--leaf:#98c7ad;--muted:#b5c5c9}
*{box-sizing:border-box}body{margin:0;background:var(--night);color:var(--cream);font:17px/1.6 "Trebuchet MS",sans-serif}
main{max-width:1180px;margin:auto;padding:24px 28px 50px}a{color:var(--leaf);text-underline-offset:5px}button{font:inherit;cursor:pointer;min-height:48px;padding:11px 20px;background:var(--cream);color:var(--night);border:1px solid var(--cream);border-radius:50px}button:hover{background:var(--orange);border-color:var(--orange)}button:disabled{opacity:.5;cursor:default}
:focus-visible{outline:3px solid var(--orange);outline-offset:5px}.mast{display:flex;justify-content:space-between;gap:12px;font:12px/1.5 "Courier New",monospace;letter-spacing:2px;text-transform:uppercase;padding-bottom:15px;border-bottom:1px solid #52616c}
header{display:grid;grid-template-columns:1.4fr 1fr;gap:50px;align-items:end;padding:42px 0 24px}h1{font:normal clamp(52px,8vw,94px)/.94 Georgia,serif;letter-spacing:-3px;margin:8px 0 14px}h1 em{color:var(--orange)}header p{max-width:390px;color:var(--muted)}.eyebrow{font:12px/1.5 "Courier New",monospace;letter-spacing:2px;text-transform:uppercase;color:var(--orange)}
.orchard{position:relative;overflow:hidden;border-radius:160px 160px 12px 12px;background:#192c34;aspect-ratio:2.65;min-height:240px}.orchard img{width:100%;height:100%;object-fit:cover;object-position:center 53%;display:block;transition:filter 1s;filter:saturate(.65)}.orchard[data-grown="true"] img{filter:saturate(1.25)}
.fruitcount{position:absolute;right:18px;bottom:15px;background:var(--night);padding:8px 18px;border:1px solid var(--orange);border-radius:50px;font:14px "Courier New",monospace}.fruitcount b{color:var(--orange)}
.deck{display:grid;grid-template-columns:1fr 1.35fr;gap:40px;margin-top:32px}.branch{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #3c505a}.branch input{accent-color:var(--orange);width:23px;height:23px}.branch span{display:block;font-size:13px;color:var(--muted)}h2{font:normal 30px Georgia,serif;margin:6px 0 12px}p{margin:10px 0 18px}.small{font-size:14px;color:var(--muted)}.primary{background:var(--orange);border-color:var(--orange);margin:20px 0 4px}
.paper{color:var(--night);background:var(--cream);padding:28px 32px;border-radius:2px 24px 2px 24px;box-shadow:7px 7px 0 #5a755f;position:relative;min-height:360px}.paper .eyebrow{color:#805021}.paper h2{font-size:33px}.paper .small{color:#455c65}.paper button{background:var(--night);color:var(--cream);border-color:var(--night)}.paper button:hover{background:#3b5d65}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.identity{display:grid;grid-template-columns:auto 1fr;gap:3px 16px;font:13px/1.7 "Courier New",monospace;background:#e8ddbf;padding:12px;overflow-wrap:anywhere}.identity dt{font-weight:bold}.identity dd{margin:0}.feedback{min-height:65px;font-size:15px;padding-top:16px}.feedback.bad{color:#a03219}.feedback.good{color:#23533f}.progress{height:4px;background:#d6c9a9;margin:14px 0 24px}.progress div{height:100%;background:#416854;transition:width .3s}
.ledger{margin-top:38px;border-top:1px solid #52616c;padding-top:20px}.ledger ul{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;list-style:none;padding:0}.ledger li{padding:14px;background:#192e38;border-left:3px solid var(--leaf);font-size:15px}.ledger code{font:12px "Courier New",monospace;color:var(--orange);display:block;margin-top:5px}.lesson{max-width:750px;padding:20px 0}.lesson strong{color:var(--orange)}footer{border-top:1px solid #52616c;padding-top:22px;font-size:14px;color:var(--muted)}[hidden]{display:none!important}
@media(max-width:700px){main{padding:18px 18px 40px}header{grid-template-columns:1fr;gap:8px;padding-top:30px}header p{margin:0 0 20px}h1{letter-spacing:-2px}.orchard{aspect-ratio:1.6;min-height:210px;border-radius:90px 90px 8px 8px}.deck{grid-template-columns:1fr;gap:24px}.paper{padding:24px}.ledger ul{grid-template-columns:1fr}.mast{font-size:10px;letter-spacing:1px}.actions button{flex:1;padding:10px}.fruitcount{right:10px;bottom:10px;font-size:12px}}
